package main

import (
	"errors"
	"fmt"
)

// Membuat Custom Error Statis
var ErrDataNotFound = errors.New("data tidak ditemukan di database")
var ErrPermissionDenied = errors.New("akses ditolak")

// Simulasi fungsi yang memicu error
func getUser(id int) (string, error) {
	if id == 0 {
		// Error bawaan
		return "", ErrDataNotFound
	}
	if id < 0 {
		// Error kustom menggunakan format
		return "", fmt.Errorf("ID tidak valid: %d", id)
	}
	return "Archon", nil
}

// Simulasi lapisan atas (Misal: API handler) yang membungkus error (Wrapping)
func apiHandler(id int) error {
	_, err := getUser(id)
	if err != nil {
		// Kita bungkus error aslinya dengan konteks tambahan menggunakan %w
		return fmt.Errorf("API GetUser gagal: %w", err)
	}
	return nil
}

func main() {
	fmt.Println("=== Simulasi Error ===")

	err := apiHandler(0)
	if err != nil {
		fmt.Println("Terjadi Kesalahan:", err)

		// Memeriksa apakah error yang terbungkus itu adalah ErrDataNotFound
		// (Sangat berguna untuk menentukan HTTP Status 404 atau 500)
		if errors.Is(err, ErrDataNotFound) {
			fmt.Println("-> Resolusi: Kirim status 404 (Not Found) ke klien.")
		}
	}
}
